  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action) => {
      state.cartItems.push(action.payload);
      state.totalQuantity += 1;
    },
    removeItem: (state, action) => {
      const index = state.cartItems.findIndex(item => item.id === action.payload);
      if (index >= 0) {
