Here is a CartComponent that uses the cart slice. We'll also need to make an async thunk for checking out, which in practice would hit your server or a payment gateway:

```jsx
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';
import { createAsyncThunk } from '@reduxjs/toolkit';

const CartComponent = () => {
  const dispatch = useDispatch();
  const { items } = useSelector(state => state.cart);

  const checkout = createAsyncThunk('cart/checkout', async () => {
    const response = await fetch('https://example.com/checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' }
    });
    const data = await response.json();
    return data;
  });

  return (
    <div>
      <h1>Cart</h1>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            {item.name} ({item.price}){' '}
            <button onClick={() => dispatch(removeItem(item.id))}>
              Remove
            </button>
            <button onClick={() => dispatch(addItem({...item, quantity: 2 }))}>
              Add quantity
            </button>
          </li>
        ))}
      </ul>
      <button onClick={() => dispatch(checkout())}>Checkout</button>
    </div>
  );
};

export default CartComponent;
```

